INSERT OR IGNORE INTO content (key, value, updated_at)
VALUES ('about', '{"heading":"About","avatar":"/about/avatar.png","avatarAlt":"Dylan Petzko","body":"# Welcome and Hello, I''m Dylan\n\nI build, run, and manage infrastructure for fun and for a living. You''re currently connected to my homelab, Rivendell!\nRivendell is a hybrid edge + cloud homelab built on Talos, GitOps and an unreasonable amount of observability for such\na small setup.\n\nBy day I work on backend, frontend, platform, and all around every type of system imaginable. If someone has a problem - I usually can create a solution for it. Outside of work and tech you can find me getting beat up on the regular via jui-jitsu, brewing my own beer and mead, or going on long walks on the beach with my dog (I don''t own a dog). In my career I''ve worked often in confidential and classified environments doing work for healthcare systems and defense systems. I''ve luckily have had the opportunity to travel the world for my work and I love every minute of what I do.\n\nAlso - My biggest strength is that I know how to exit vim.\n\n# What I''m into\n\n- **DevOps** - I''m a lazy developer - and I like to develop tools which make the process for everyone easier. The less work we _have_ to do, and the more we get done means I''ve done my job and everyones happier.\n- **BJJ** - After a long day - nothing hits harder than getting beat up (and beating up) my friends and colleagues.\n- **Homebrew** - Not the package manager - actual home brewing! I don''t drink much, but crafting my own flavors and recipes of different types of wine and beer has become a growing passion.\n- **Tech** - I love computers and give unlimited funs I would build all types of creative and powerful machines.\n- **Gaming** - An avid gamer since I could move my fingers. From WoW, to PoE, to minecraft I''ve enjoyed a variety of games and found joy in spending a lot of time with friends within different worlds.\n\n## Find me\n\nDrop into the **contact** section for links, or hit `:` to jump around right to the ''contact'' section.\n\n"}', CAST(strftime('%s','now') AS INTEGER) * 1000);

INSERT OR IGNORE INTO content (key, value, updated_at)
VALUES ('contacts', '[{"type":"github","url":"https://github.com/petzkod5","description":"Code, dotfiles, and this very site. Most of what I build lives here.","click":true,"newTab":true,"copy":false},{"type":"linkedin","url":"https://linkedin.com/in/dylan-petzko","description":"For professionals — inquire within. I''m open to any and all inquiries!","click":true,"newTab":true,"copy":false},{"type":"gmail","url":"dylan@petzko.sh","description":"The direct line. Email me about work, projects, or homebrew recipes.","click":true,"newTab":false,"copy":false},{"type":"instagram","url":"instagram.com/dylanpetzko","description":"Contact me on Instagram! See my adventures. Or not, I rarely post here.","click":true,"newTab":true,"copy":false},{"type":"discord","url":"petzko.","description":"Love a good conversation - one of the best ways to chat me up.","click":false,"newTab":false,"copy":true}]', CAST(strftime('%s','now') AS INTEGER) * 1000);

INSERT OR IGNORE INTO content (key, value, updated_at)
VALUES ('portfolio', '[{"type":"github","name":"My Resume","url":"github.com/petzkod5/resume","icon":"","company":"","description":"My resume as code! The exact resume you''ll find on this website is built from HTML and LaTeX in this repository."},{"type":"github","name":"Rivendell","url":"github.com/petzkod5/rivendell-talos-cluster","icon":"","company":"","description":"Rivendell - a place of magic. No - it''s just my Talos cluster, which can be deployed over and over again using GitOps through ArgoCD. With the use of SOPS + age + Argo + Helmfile, I can redeploy this cluster in less than 20 minutes. Maybe it is magic."},{"type":"github","name":"Bash Stow","url":"github.com/petzkod5/bash-stow","icon":"","company":"","description":"The GNU tool ''stow'' is used to symlink files to a fixed destination. It''s often used (at least by me) for managing dotfiles and configuration. On isolated or secure systems this tool is often not found. A replacement for it without all of GNU is this! A rewrite of the tool in pure Bash - it''s not fast - it''s not pretty. But it works."},{"type":"github","name":"JACL - Just Another Config Language","url":"github.com/petzkod5/just_another_config_language","icon":"","company":"","description":"There''s no need for another configuration language. But this one is mine. My attempt at lexical analysis and token parsing while learning how programming languages are put together. This language uses full lexing, token parsing, and an abstract syntax tree to make a robust parser for a very, very opinionated configuration language."},{"type":"Work Project","name":"Aegis Weapon System Test Harness","url":"","icon":"","company":"Lockheed Martin","description":"Developed and maintained a custom test harness for mission-critical weapon systems, performing automated regression and integration testing scaling across several customer baselines. Used to detect issues before they are deployed to production customer environments. Test sets maintained exceeded 4500 tests and saved many junior engineers countless hours manually testing against old procedure documents."},{"type":"Work Project","name":"Aegis Weapon System Developer CLI Tool","url":"","icon":"","company":"Lockheed Martin","description":"Developed a CLI tool which helped developers on several customer baseline projects save hours doing repetitive tasks like building, testing, and managing baseline projects. The tool, built in Python, was able to aggregate several other developer tools that were being used into one platform, and was widely recognized and used by developers. Analytics built into the tool showed a userbase of 60% of the developer department, and it saved on average 1-2 hours a day per engineer."},{"type":"Work Project","name":"Army Command & Control System","url":"","icon":"","company":"Lockheed Martin","description":"Led as one of the lead Software Architects for the Army''s new Command & Control system meant to overhaul how the Army does digital mission control and how battlefield information is handled. Rooted in AI integration - I lead the platform architecture design and software implementation for the Lockheed Martin Prototype. Establishing best practices in security, devops, and maintainability while reducing costs were just some of my achievements."}]', CAST(strftime('%s','now') AS INTEGER) * 1000);

